  if ((i & 1) == 0) {
    *pi = (int) (i >> 1);
    return sz;
  }
  i = i >> 1;
  i |= (sz == 1 ? SIGN_MASK_ONEBYTE : (sz == 2 ? SIGN_MASK_TWOBYTE : SIGN_MASK_FOURBYTE));

